from dataclasses import FrozenInstanceError
from decimal import Decimal

import pytest

from payment.application.authorize_payment import AuthorizePayment
from payment.domain.money import Money


@pytest.mark.parametrize("amount", [Decimal("0"), Decimal("-1"), Decimal("-0.01")])
def test_a_non_positive_amount_is_rejected(amount: Decimal) -> None:
    with pytest.raises(ValueError, match="positive"):
        Money(amount, "EUR")


@pytest.mark.parametrize("amount", [Decimal("0.01"), Decimal("1"), Decimal("42.50")])
def test_a_positive_amount_is_accepted(amount: Decimal) -> None:
    assert Money(amount, "EUR").amount == amount


@pytest.mark.parametrize("currency", ["", " ", "   "])
def test_a_blank_currency_is_rejected(currency: str) -> None:
    with pytest.raises(ValueError, match="currency"):
        Money(Decimal("1"), currency)


def test_the_currency_is_normalised_to_upper_case() -> None:
    assert Money(Decimal("1"), "eur").currency == "EUR"


def test_money_is_immutable() -> None:
    money = Money(Decimal("1"), "EUR")
    with pytest.raises(FrozenInstanceError):
        money.amount = Decimal("2")  # type: ignore[misc]


def test_the_authorize_payment_handler_is_not_meant_to_be_subclassed() -> None:
    assert getattr(AuthorizePayment, "__final__", False) is True
EOF
